import{_ as d,o as t,c as a,a2 as o}from"./chunks/framework.sc8Z_ZE3.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"MPanel","text":"服务器管理面板文档","tagline":"web/panel、core、agent 三端分离；沿用 1Panel 的 /opt/mpanel 与 systemd 约定；站点管理用 Caddy。","actions":[{"theme":"brand","text":"从源码安装","link":"/guide/install"},{"theme":"alt","text":"与 1Panel 的差异","link":"/guide/faq"}]},"features":[{"title":"三端分离","details":"web/panel 只负责界面；core 负责登录、机器注册、隧道与代理；agent 在目标主机执行站点、数据库、容器、文件、终端与计划任务。"},{"title":"1Panel 风格部署","details":"安装根 /opt/mpanel，配置 conf/app.yaml 与 conf/agent.yaml，二进制放在 /usr/local/bin，服务用 mpanel-core.service / mpanel-agent.service。"},{"title":"Caddy 容器化","details":"Caddy 以 mpanel-caddy 编排运行，站点页一键安装；每站点生成 sites.d/*.caddy，apply 在容器内 validate → 备份 → 原子替换 → reload → 回滚。"},{"title":"长任务不阻塞","details":"站点应用、编排启停、镜像拉取等耗时操作转为后台任务，立即返回 202；进度弹窗与任务中心展示状态、日志与结果。"},{"title":"能力缺失可降级","details":"没有 Caddy 容器、Docker、PostgreSQL 客户端、Redis 客户端或 PTY 时进程照常启动；列表返回 available=false，写操作返回 UNAVAILABLE 与可执行提示。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1795742187000}'),c={name:"index.md"};function l(r,e,n,i,s,p){return t(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="一句话定位" tabindex="-1">一句话定位 <a class="header-anchor" href="#一句话定位" aria-label="Permalink to &quot;一句话定位&quot;">​</a></h2><p>MPanel 是一个三端分离的服务器管理面板：<code>web/panel</code> 是 Vue 3 + Vite + Vue Router + Naive UI 单页前端，<code>core</code> 是控制面（登录、机器注册、健康检查、隧道与 REST/WS 代理），<code>agent</code> 是功能面（在每台被管主机上执行站点、证书、数据库、容器、文件、终端与计划任务）。<strong>面板只连接 core</strong>，不直连 agent；每台机器的页面以独立标签页打开，多台机器的页面可以同时混合管理工作。</p><h2 id="与-1panel-的取舍" tabindex="-1">与 1Panel 的取舍 <a class="header-anchor" href="#与-1panel-的取舍" aria-label="Permalink to &quot;与 1Panel 的取舍&quot;">​</a></h2><h3 id="沿用-1panel-的部署约定" tabindex="-1">沿用 1Panel 的部署约定 <a class="header-anchor" href="#沿用-1panel-的部署约定" aria-label="Permalink to &quot;沿用 1Panel 的部署约定&quot;">​</a></h3><p>MPanel 刻意保持 1Panel 用户熟悉的路径与进程模型：</p><table tabindex="0"><thead><tr><th>项目</th><th>1Panel</th><th>MPanel</th></tr></thead><tbody><tr><td>安装根</td><td><code>/opt/1panel</code></td><td><code>/opt/mpanel</code></td></tr><tr><td>配置</td><td><code>conf/app.yaml</code></td><td><code>conf/app.yaml</code>（core）、<code>conf/agent.yaml</code>（agent）</td></tr><tr><td>数据 / 日志 / 数据库 / 备份</td><td><code>data/</code>、<code>log/</code>、<code>db/</code>、<code>backup/</code></td><td><code>data/</code>、<code>log/</code>、<code>db/</code>、<code>backup/</code>，另有 <code>tmp/</code></td></tr><tr><td>二进制</td><td><code>/usr/local/bin/1panel-core</code>、<code>1panel-agent</code></td><td><code>/usr/local/bin/mpanel-core</code>、<code>mpanel-agent</code>、<code>mpctl</code></td></tr><tr><td>systemd 服务</td><td><code>1panel-core.service</code>、<code>1panel-agent.service</code></td><td><code>mpanel-core.service</code>、<code>mpanel-agent.service</code></td></tr><tr><td>控制命令</td><td><code>1pctl</code></td><td><code>mpctl</code>（<code>/usr/bin/mpctl</code> 软链）</td></tr></tbody></table><p>这意味着备份、迁移、权限与 SELinux 的处理方式基本可以照搬 1Panel 的经验，运维不需要学习一套新目录。</p><h3 id="网站管理改用-caddy" tabindex="-1">网站管理改用 Caddy <a class="header-anchor" href="#网站管理改用-caddy" aria-label="Permalink to &quot;网站管理改用 Caddy&quot;">​</a></h3><p>1Panel 用 nginx 管理网站；MPanel 用 Caddy，原因不是偏好，而是站点模型更简单可靠：</p><ol><li><strong>Caddyfile 片段化</strong>：每个站点生成一个 <code>sites.d/&lt;siteId&gt;.caddy</code> 片段，主 <code>Caddyfile</code> 只有 <code>import sites.d/*.caddy</code>。增删站点是增删文件，不需要在一个大配置里做文本手术。</li><li><strong>自动 HTTPS</strong>：域名只要解析到本机，Caddy 默认自动申请和续期证书；<code>tls internal</code>、<code>tls off</code> 只是配置项，不需要额外维护 certbot 与续期定时任务。</li><li><strong>validate / reload / 回滚是内建流程</strong>：apply 前先 <code>caddy validate</code>，通过后备份现有目录、原子替换、<code>caddy reload</code>；reload 失败自动恢复备份并再次 reload。整个过程可以给出明确的 <code>stage</code> 与 <code>caddyOutput</code>。</li><li><strong>结构化配置边界更清晰</strong>：MPanel 只接受结构化站点配置，不支持粘贴原始 Caddyfile 片段；所有进入 Caddyfile 的字符串都经过校验与转义，避免 nginx 时代常见的配置注入与手写错误。</li></ol><h2 id="实现状态" tabindex="-1">实现状态 <a class="header-anchor" href="#实现状态" aria-label="Permalink to &quot;实现状态&quot;">​</a></h2><p>Go 重写仍在进行中。本站严格区分「已实现」与「规划中」，不把设计当成已交付功能：</p><table tabindex="0"><thead><tr><th>能力</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>REST API v1 与隧道协议 v1 契约</td><td>已冻结</td><td>见 <a href="/docs/api/contract.html">REST API 契约</a> 与 <a href="/docs/api/protocol.html">隧道协议</a></td></tr><tr><td>配置模型（<code>app.yaml</code> / <code>agent.yaml</code>、<code>MPANEL_*</code> 覆盖、目录创建、原子写）</td><td>已实现</td><td><code>server/core/config</code></td></tr><tr><td>信封、错误码、分页、隧道帧模型</td><td>已实现</td><td><code>server/core/protocol</code></td></tr><tr><td>原子 JSON 存储</td><td>已实现</td><td><code>server/core/store</code></td></tr><tr><td><code>mpanel-core</code> / <code>mpanel-agent</code> / <code>mpctl</code> 入口</td><td>已实现</td><td><code>server/cmd/</code></td></tr><tr><td>认证、隧道、机器代理、站点/数据库/容器/文件/终端/任务模块</td><td>已实现</td><td>按契约实现，能力缺失时降级</td></tr><tr><td>web/panel 前端</td><td>已有源码</td><td>Vue 3 + Vite + Vue Router + Naive UI；只连 core，多机标签工作台</td></tr></tbody></table><p>安装步骤按目标形态书写；涉及尚未落地的二进制时，页面会明确标注，不要据此认为该步骤已经可执行。</p><h2 id="文档地图" tabindex="-1">文档地图 <a class="header-anchor" href="#文档地图" aria-label="Permalink to &quot;文档地图&quot;">​</a></h2><ul><li><a href="/docs/guide/install.html">从源码安装</a>：构建、放置二进制、systemd 单元、首次启动 bootstrap token。</li><li><a href="/docs/guide/config.html">配置文件与环境变量</a>：<code>/opt/mpanel</code> 目录树、<code>app.yaml</code> 与 <code>agent.yaml</code> 全部字段、<code>MPANEL_*</code> 覆盖规则。</li><li><a href="/docs/guide/deploy.html">生产部署</a>：反向代理（Caddy / nginx）、升级、备份、SELinux 与权限。</li><li><a href="/docs/guide/sites.html">站点与 Caddy</a>：站点模型、apply 流程、证书扫描。</li><li><a href="/docs/guide/databases.html">数据库与 dbx</a>：PostgreSQL / Redis 档案、备份恢复、dbx iframe 与 handoff。</li><li><a href="/docs/guide/edge.html">边缘节点</a>：入网密钥、快照、离线作业。</li><li><a href="/docs/api/contract.html">REST API 契约</a>：所有端点、请求/响应形状与错误码。</li><li><a href="/docs/api/protocol.html">隧道协议</a>：stdio / reverse-ws 的帧格式、分块与多路复用。</li><li><a href="/docs/ops/troubleshooting.html">故障排查</a>：机器离线、Caddy apply 失败、PTY、dbx、入网 403。</li></ul>',16)])])}const g=d(c,[["render",l]]);export{m as __pageData,g as default};
